from collections import deque

def check_graph(edges, n):
    adj = [[] for _ in range(n)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    degs = [len(a) for a in adj]
    maxdeg = max(degs)
    mindeg = min(degs)

    min_cycle = n+1
    for start in range(n):
        dist = [-1]*n
        parent = [-1]*n
        q = deque([start])
        dist[start] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u] and parent[v] != u:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
        if min_cycle <= 4:
            break
    return maxdeg, mindeg, min_cycle

def try_pattern(offsets_even, offsets_odd):
    n = 24
    edges = set()
    for i in range(n):
        edges.add((i, (i+1) % n))
    for i in range(0, n, 2):
        for off in offsets_even:
            edges.add((i, (i+off) % n))
    for i in range(1, n, 2):
        for off in offsets_odd:
            edges.add((i, (i+off) % n))

    norm = set()
    for u,v in edges:
        if u > v: u,v = v,u
        norm.add((u,v))
    return norm

