for eo, oo in [(7,13), (5,19), (7,17), (11,13), (7,11), (5,7), (9,15), (13,7)]:
    e = try_pattern([eo], [oo])
    d = check_graph(e, 24)
    print(f"even+{eo}, odd+{oo}: {d}")
